import { Component, h, Prop } from '@stencil/core';

// Component ui-options-btn: Deprecated
@Component({
  tag: 'ui-options-btn',
  styleUrl: 'ui-options-btn.css',
  shadow: true
})
export class UiOptionsBtnComponent {
  @Prop() label: string;
  @Prop() href: string;
  @Prop() icon: string;

  render() {
    const iconClasses = ['text-2xl leading-none', `icon-${this.icon}`].join(' ').trim().replace(/\s+/g, ' ');

    return (
      <div class="bg-primary text-white px-4">
        <a href={this.href} class="flex items-center gap-2 text-base font-bold whitespace-nowrap">
          {this.icon && <i class={iconClasses} />}
          {this.label}
        </a>
      </div>
    );
  }
}
